ng></div><p class="form-hint">档案保存在本浏览器。P4 自动同步与更多设备绑定将在后续接入。</p><div v-if="editorError" class="form-error" role="alert">{{ editorError }}</div><div class="modal-footer"><NativeButton type="button" class="secondary-button" @click="closeEmployeeEditor">取消</NativeButton><NativeButton class="primary-button" type="submit" :disabled="photoLoading" @click="saveEmployee"><AppIcon name="check" />保存档案</NativeButton></div></form></section></div>
    <div v-if="historyModalVisible" class="modal-backdrop" @click.self="closeHistory"><section class="modal history-modal" role="dialog" aria-modal="true" aria-labelledby="history-title"><div class="modal-header"><div><div class="eyebrow">TELEMETRY HISTORY</div><h2 id="history-title">{{ activeHistoryConfig.name }}历史记录</h2></div><NativeButton class="icon-button" @click="closeHistory" aria-label="关闭历史记录"><AppIcon name="close" /></NativeButton></div><div class="history-summary"><span>最高 <strong>{{ historyMax }} {{ activeHistoryConfig.unit }}</strong></span><span>最低 <strong>{{ historyMin }} {{ activeHistoryConfig.unit }}</strong></span><span>共 <strong>{{ activeHistoryRows.length }} 条记录</strong></span></div><MetricChart :rows="historyRecords[activeHistoryKey]" :label="activeHistoryConfig.name" :unit="activeHistoryConfig.unit" chart-id="history" /><div class="history-table-scroll"><table><thead><tr><th>记录时间</th><th>{{ activeHistoryConfig.name }}</th></tr></thead><tbody><tr v-for="(row, index) in activeHistoryRows.slice(0, 200)" :key="index"><td>{{ row.time }}</td><td>{{ row.text }} {{ activeHistoryConfig.unit }}</td></tr></tbody></table><div v-if="!activeHistoryRows.length" class="table-empty">暂无历史数据</div></div><p class="form-hint">最近 200 条明细 · 当前浏览器采集记录</p></section></div>
